// Ikon lucide sebagai SVG inline.
function icon(string $name, int $size = 18): string
{
    static $cache = [];
    $k = $name . $size;
    if (isset($cache[$k])) return $cache[$k];
    if (!isset(ICON_PATHS[$name])) return '';
    return $cache[$k] = '<svg aria-hidden="true" class="shrink-0 lucide lucide-' . $name . '" xmlns="http://www.w3.org/2000/svg" width="' . $size . '" height="' . $size
        . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' . ICON_PATHS[$name] . '</svg>';
}

function ikonPeralatan(string $nama): string
{
    $n = mb_strtolower($nama);
    if (preg_match('/\bac\b/', $n)) return 'air-vent';
    if (strpos($n, 'kulkas') !== false) return 'refrigerator';
    if (strpos($n, 'laptop') !== false) return 'laptop';
    if (strpos($n, 'kipas') !== false) return 'fan';
    if (strpos($n, 'lampu') !== false) return 'lightbulb';
    if (strpos($n, 'dispenser') !== false) return 'settings';
    return 'plug';
}
